    private data class HeadSeed(val unchangedTorsoAndBladeSha256:String,val actualNewHeadSha256:String)
    private val newHead=mapOf(
        "veteran/attack_overhead" to HeadSeed("8bea6d5ab70a8fa9b0b958f4aa9f5a6392780148d56a2fff485cbfd02e871e97","acd281a81ab9fcee3b1457bd2ef549248cd59d44d1f218eb783ccc44518135cc"),
        "veteran/attack_left" to HeadSeed("78c11011cf5364e05384001792e65a8cbd131e3f0b9770bf20d265ce0ef0a47a","51ec4f397e4c9e1f1e5e9e3f5129e0431b61669e0d8f42c81812543f4e7b8a32"),
        "veteran/attack_right" to HeadSeed("6406548f25d58f8775f09b51b83ed33b578c860c65c01fb5bf882bca706e381c","bfc7a6369923473aeb5c7e2e035d79e95a0aa26eab6e3f7b78d844e1f11ff249"),
        "veteran/idle" to HeadSeed("8ae6a34d2f810f8d4ef21e621c30c2c630a1e4f1fbdc0c8302403f99c703722d","3bb8abe66e8d2ee3eceb15dd6a9e83b48afdeed5597d6e46821b23e1b95a1568"),
        "veteran/walk" to HeadSeed("e6f4e1d3df3155c7080c1584a4fb41db094e8dd5ab0f79393198abe82fce4f63","0dd4073f72fcd8b075cda5e91618f0c21e72e09fff71b600040ed9b53512a05b")
    )
    fun verify(key:String,samples:List<AttackPoseSample>) {
        val seed=all.getValue(key);val digest=MessageDigest.getInstance("SHA-256")
        val torsoBladeDigest=MessageDigest.getInstance("SHA-256");val headDigest=MessageDigest.getInstance("SHA-256")
        for(time in seed.times) {
            val row=samples.single {it.sourceSeconds==time}
            val values=listOf(row.sourceSeconds)+listOf(row.contact.head,row.contact.bodyBottom,row.contact.bodyTop,row.bladeBase,row.bladeTip).flatMap {listOf(it.x,it.y,it.z)}
            digest.update(ByteBuffer.allocate(16*8).apply {for(value in values)putDouble(value)}.array())
            headDigest.update(ByteBuffer.allocate(4*8).apply {for(value in values.take(4))putDouble(value)}.array())
            torsoBladeDigest.update(ByteBuffer.allocate(13*8).apply {putDouble(row.sourceSeconds);for(value in values.drop(4))putDouble(value)}.array())
        }
        fun hex(d:MessageDigest)=d.digest().joinToString(""){"%02x".format(it)}
        val head=newHead[key]
        if(head==null)assertEquals("Every preserved seed has its explicitly bound anchors: $key",seed.anchorsSha256,hex(digest))
        else {
            assertEquals("Original torso and blade anchors remain exact: $key",head.unchangedTorsoAndBladeSha256,hex(torsoBladeDigest))
            assertEquals("Head anchors match the actual new head source: $key",head.actualNewHeadSha256,hex(headDigest))
        }
        assertTrue(samples.size>=seed.times.size)
        assertTrue(samples.all {it.bladeGrip.position.isFinite() && it.bladeGrip.rotation.normalizedOrNull()!=null && it.bladeGripInterpolationErrorToNextMeters in 0.0..0.001})
        assertTrue(samples.all {val q=it.bladeGrip.rotation;kotlin.math.abs(q.x*q.x+q.y*q.y+q.z*q.z+q.w*q.w-1.0)<1e-6})
        assertEquals(0.0,samples.last().bladeGripInterpolationErrorToNextMeters,0.0)
    }
